CREATE OR REPLACE FUNCTION public.extract_class_quiz_keys() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE question_item jsonb; keys jsonb; BEGIN IF NEW.kind='quiz' THEN IF NEW.questions IS NULL OR jsonb_array_length(NEW.questions) NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'A quiz needs 1 to 50 questions'; END IF; FOR question_item IN SELECT value FROM jsonb_array_elements(NEW.questions) LOOP IF jsonb_typeof(question_item->'answer') IS DISTINCT FROM 'number' OR (question_item->>'answer')::integer < 0 OR (question_item->>'answer')::integer >= jsonb_array_length(question_item->'options') THEN RAISE EXCEPTION 'Invalid quiz answer'; END IF; END LOOP; SELECT jsonb_agg(a.item->'answer' ORDER BY a.ord) INTO keys FROM jsonb_array_elements(NEW.questions) WITH ORDINALITY a(item,ord); INSERT INTO public.class_quiz_keys VALUES(NEW.id,keys); UPDATE public.class_content SET questions=(SELECT jsonb_agg(a.item - 'answer' ORDER BY a.ord) FROM jsonb_array_elements(NEW.questions) WITH ORDINALITY a(item,ord)) WHERE id=NEW.id; END IF; RETURN NEW; END $$;